package com.creatorhub.servlet; import com.creatorhub.dao.CreatorDAO; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.*; @WebServlet("/join-challenge") public class JoinChallengeServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{HttpSession h=r.getSession(false);if(h==null||h.getAttribute("studentId")==null){s.sendRedirect(r.getContextPath()+"/?error=Login+to+join");return;}try{boolean ok=new CreatorDAO().join(Integer.parseInt(r.getParameter("challengeId")),(Integer)h.getAttribute("studentId"));s.sendRedirect(r.getContextPath()+"/challenges?message="+(ok?"Joined+challenge":"Already+joined"));}catch(Exception e){s.sendRedirect(r.getContextPath()+"/challenges?error=Unable+to+join");}}}
